from taf.rfrl.procedures.resources.python.bts.sw.sw_stream import SwStream
from taf.rfrl.procedures.resources.python.bts.sw.sw_version_du import SwVersionDu
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import Api


class SwDu:
    """ Handles BTS software management on DU. """

    STREAM_25R1 = SwStream(name='25R1')
    STREAM_25R2 = SwStream(name='25R2')
    STREAM_25R3 = SwStream(name='25R3')
    STREAM_26R1 = SwStream(name='26R1')

    def __init__(self, api: Api, api_alias: str):
        """
        :param api: API used for managing software on BTS
        :param api_alias: name of opened API connection which this software manager should use
        """
        self._version = None
        self._api = api
        self._api_alias = api_alias

    @property
    def version(self) -> SwVersionDu:
        """ Returns representation of software version currently uploaded on DU. """
        if self._version is None:
            self.load()
        return self._version

    def load(self):
        """ Loads information about software version currently uploaded on DU. """
        du_info = self._api.get_vdu_state_data(vdu_connection=self._api_alias)
        self._version = SwVersionDu(name=du_info['software_version'])
